import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Inject,
} from '@angular/core'
import { state, sequences, ModuleDefinition } from 'cerebral'
import { setupTestComponent, createMockCdr } from './helpers'
import { TestBed, waitForAsync } from '@angular/core/testing'
import { CommonModule } from '@angular/common'
import { By } from '@angular/platform-browser'
import { AppService } from '../src/AppService'
import { CerebralComponent } from '../src/CerebralComponent'
import { connect } from '../src/connect'
import { CerebralTest } from 'cerebral/test'

// Simple state component for unit tests
@Component({
  template: `<div data-testid="count-display">{{ count }}</div>`,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
class StateComponent extends CerebralComponent {
  count = 0

  constructor(
    @Inject(ChangeDetectorRef) cdr: ChangeDetectorRef,
    @Inject(AppService) app: AppService
  ) {
    super(cdr, app)
  }
}

// Connected counter component
@Component({
  selector: 'test-connected-component',
  template: `
    <div>
      <div data-testid="count">{{ count }}</div>
      <div data-testid="doubled">{{ doubled }}</div>
      <button data-testid="increment" (click)="increment()">+</button>
    </div>
  `,
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
@connect({
  count: state`count`,
  doubled: state`doubled`,
  increment: sequences`increment`,
})
class TestConnectedComponent extends CerebralComponent {
  count!: number
  doubled!: number
  increment!: () => void

  constructor(
    @Inject(ChangeDetectorRef) cdr: ChangeDetectorRef,
    @Inject(AppService) app: AppService
  ) {
    super(cdr, app)
  }
}

type State = {
  count: number
  doubled: number
}

const appState: State = {
  count: 1,
  get doubled() {
    return this.count * 2
  },
}

// Create a test cerebral module
const testModule: ModuleDefinition = {
  state: appState,
  sequences: {
    increment: [
      ({ store, get }: any) => store.set('count', get(state`count`) + 1),
    ],
  },
}

describe('connect functionality tests', () => {
  it('should connect state using connect function', () => {
    // Test direct connection
    const test = CerebralTest({ state: { count: 42 } })

    @connect({
      count: state`count`,
    })
    class SimpleComponent extends CerebralComponent {
      count = 0
    }

    const cdr = createMockCdr()
    const component = new SimpleComponent(cdr, test.controller)

    setupTestComponent(component, { count: state`count` })

    expect(component.count).toBe(42)

    test.setState('count', 100)
    component.onUpdate({}, true)

    expect(component.count).toBe(100)
  })

  it('should work with StateComponent in Angular context', waitForAsync(() => {
    const simpleModule: ModuleDefinition = { state: { count: 42 } }
    const appService = new AppService(simpleModule)

    TestBed.configureTestingModule({
      imports: [CommonModule, StateComponent],
      providers: [{ provide: AppService, useValue: appService }],
    })
      .compileComponents()
      .then(() => {
        const fixture = TestBed.createComponent(StateComponent)
        const component = fixture.componentInstance

        setupTestComponent(component, { count: state`count` })
        fixture.detectChanges()

        const countElement = fixture.debugElement.query(
          By.css('[data-testid="count-display"]')
        )
        expect(countElement.nativeElement.textContent).toBe('42')

        appService.getModel().set(['count'], 100)
        appService.flush()
        fixture.detectChanges()

        expect(countElement.nativeElement.textContent).toBe('100')
      })
  }))

  it('should integrate with Angular using TestBed', waitForAsync(() => {
    const appService = new AppService(testModule)

    TestBed.configureTestingModule({
      imports: [CommonModule, TestConnectedComponent],
      providers: [{ provide: AppService, useValue: appService }],
    })
      .compileComponents()
      .then(() => {
        const fixture = TestBed.createComponent(TestConnectedComponent)
        fixture.detectChanges()

        const countElement = fixture.debugElement.query(
          By.css('[data-testid="count"]')
        )
        const doubledElement = fixture.debugElement.query(
          By.css('[data-testid="doubled"]')
        )
        const incrementButton = fixture.debugElement.query(
          By.css('[data-testid="increment"]')
        )

        expect(countElement.nativeElement.textContent.trim()).toBe('1')
        expect(doubledElement.nativeElement.textContent.trim()).toBe('2')

        incrementButton.triggerEventHandler('click', null)
        appService.flush()
        fixture.detectChanges()

        expect(countElement.nativeElement.textContent.trim()).toBe('2')
        expect(doubledElement.nativeElement.textContent.trim()).toBe('4')
      })
  }))

  it('should connect multiple state values and sequences', () => {
    @connect({
      count: state`count`,
      doubled: state`doubled`,
      increment: sequences`increment`,
    })
    class TestComponent extends CerebralComponent {
      count: number = 0
      doubled: number = 0
      increment = () => {}
    }

    const app = new AppService(testModule)
    const cdr = createMockCdr()
    const component = new TestComponent(cdr, app)

    setupTestComponent(component, {
      count: state`count`,
      doubled: state`doubled`,
      increment: sequences`increment`,
    })

    expect(component.count).toBe(1)
    expect(component.doubled).toBe(2)

    component.increment()
    app.flush()
    component.onUpdate({}, true)

    expect(component.count).toBe(2)
    expect(component.doubled).toBe(4)
  })

  it('should handle regular class decoration with @connect', () => {
    @connect({
      count: state`count`,
      doubled: state`doubled`,
      increment: sequences`increment`,
    })
    class RegularClass {
      count: number = 0
      doubled: number = 0
      increment!: () => void
    }

    expect(RegularClass.prototype).toHaveProperty('ngOnInit')
    expect(RegularClass.prototype).toHaveProperty('ngAfterViewInit')
    expect(RegularClass.prototype).toHaveProperty('ngOnDestroy')
  })
})
